import { pxToRem } from "../../helpers";
import { StyleFn } from "..";

const SpinnerLabel: StyleFn = (theme, mode) => {
  const { color, font, size } = theme;
  const textColor = color.text.neutral.default[mode];
  return {
    position: "absolute",
    top: `calc(100% + ${size.spacing[8]})`,
    left: `calc(-${size.spacing[64]})`,
    right: `calc(-${size.spacing[64]})`,
    fontSize: font.size.small,
    lineHeight: font.lineheight.small,
    textAlign: "center",
    color: textColor,
  };
};

export const Spinner: StyleFn = (theme, mode) => {
  const { color, font, size } = theme;
  const textColor = color.text.neutral.default[mode];
  const circleColor = color.surface.feedback.information.default[mode];
  return {
    "@keyframes circle": {
      to: { transform: "rotate(360deg)" },
    },
    root: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      minWidth: size.spacing[24],
      width: size.spacing[24],
      height: size.spacing[24],
      overflow: "visible",
      fontSize: font.size.small,
      margin: 3,
      color: textColor,
      position: "relative",
      "&:before": {
        position: "absolute",
        content: '""',
        top: 0,
        bottom: 0,
        left: 0,
        right: 0,
        border: `3px solid ${circleColor}`,
        borderRightColor: "transparent !important",
        borderRadius: "50%",
        animation: "$circle .75s linear infinite",
      },
    },
    label: SpinnerLabel(theme, mode),
    _medium: {
      minWidth: pxToRem(64 - 6),
      width: pxToRem(64 - 6),
      height: pxToRem(64 - 6),
      borderWidth: size.spacing[4],
    },
  };
};

export const Progresscircle: StyleFn = (theme, mode) => {
  const { color, font, size } = theme;
  const textColor = color.text.neutral.default[mode];
  const circleColor = color.surface.feedback.information.default[mode];
  const backgroundColor = color.surface.interaction.default[mode];
  const trackColor = color.surface.componentbackground.moderate[mode];

  return {
    root: {
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      color: textColor,
      fontSize: font.size.small,
      lineHeight: font.lineheight.small,
      minWidth: size.spacing[24],
      width: size.spacing[24],
      height: size.spacing[24],
      margin: 3,
      borderRadius: "50%",
      position: "relative",
      background: `conic-gradient(${circleColor} calc(var(--percentage)*1%), ${trackColor} 0)`,
      "&:before": {
        content: '""',
        position: "absolute",
        top: 3,
        left: 3,
        right: 3,
        bottom: 3,
        borderRadius: "50%",
        backgroundColor: backgroundColor,
      },
      "& > div[role='status']": {
        fontWeight: font.weight.bold,
        position: "absolute",
      },
    },
    label: SpinnerLabel(theme, mode),
    _medium: {
      minWidth: pxToRem(64 - 6),
      width: pxToRem(64 - 6),
      height: pxToRem(64 - 6),
    },
  };
};

export const Dots: StyleFn = (theme, mode) => {
  const { color, size } = theme;
  const circleColor = color.surface.feedback.information.default[mode];
  return {
    "@keyframes wave": {
      ["0%"]: {
        transform: "translate(0, 0)",
        opacity: 1,
      },
      ["30%"]: {
        transform: "translate(0, -4px)",
        opacity: 0.5,
      },
      ["60%"]: {
        transform: "translate(0, 0)",
        opacity: 1,
      },
      ["100%"]: {
        transform: "translate(0, 0)",
        opacity: 1,
      },
    },
    root: {
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
    },
    item: {
      display: "inline-block",
      marginRight: size.spacing[8],
      width: size.spacing[8],
      height: size.spacing[8],
      borderRadius: size.spacing[8],
      backgroundColor: circleColor,
      "&:first-child": {
        animation: "$wave 1s 0.2s ease infinite",
      },
      "&:nth-child(even)": {
        animation: "$wave 1s 0.4s ease infinite",
      },
      "&:last-child": {
        marginRight: 0,
        animation: "$wave 1s 0.5s ease infinite",
      },
    },
  };
};
